import{_ as t,o as r,c as s,a3 as a}from"./chunks/framework.Ki30n65y.js";const o="/depgate/screenshots/waiver-request.png",i="/depgate/screenshots/waivers-user.png",g=JSON.parse('{"title":"Request a waiver","description":"","frontmatter":{},"headers":[],"relativePath":"developers/waiver-requests.md","filePath":"developers/waiver-requests.md"}'),n={name:"developers/waiver-requests.md"};function d(h,e,p,l,c,u){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="request-a-waiver" tabindex="-1">Request a waiver <a class="header-anchor" href="#request-a-waiver" aria-label="Permalink to &quot;Request a waiver&quot;">​</a></h1><p>When a package version you need is blocked, you can ask the security team for a <strong>waiver</strong>: a time-limited permission to use that version. If they approve it, DepGate creates an exception and the version installs until the expiry date.</p><div class="tip custom-block"><p class="custom-block-title">Check for an allowed version first</p><p>A waiver is for when no allowed version works for you. <a href="./package-check">Package check</a> usually shows a newer version that is allowed and fixes the issue the policy found.</p></div><h2 id="request-a-waiver-1" tabindex="-1">Request a waiver <a class="header-anchor" href="#request-a-waiver-1" aria-label="Permalink to &quot;Request a waiver&quot;">​</a></h2><ol><li><p>In the sidebar, choose <strong>Waiver requests</strong>, then <strong>Request waiver</strong>. You can also choose <strong>Request waiver</strong> on a blocked version in Package check; the form then opens with the package and version filled in.</p></li><li><p>Fill in the form:</p><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Ecosystem</strong></td><td>The package&#39;s ecosystem.</td></tr><tr><td><strong>Package name</strong></td><td>The exact package name.</td></tr><tr><td><strong>Versions</strong> (optional)</td><td>The versions you need. Add single versions with <strong>+ Version</strong> or ranges with <strong>+ Version range</strong>. Leave empty to ask for every version.</td></tr><tr><td><strong>Applies to</strong></td><td><strong>All repositories</strong>, or only the repositories you use.</td></tr><tr><td><strong>Needed until</strong></td><td>When you expect to stop needing it. The reviewer may choose a different date.</td></tr><tr><td><strong>Reason</strong></td><td>What you need it for, and why it is safe. Reviewers decide on this, so be specific: the project, the ticket, and your plan to move off it.</td></tr></tbody></table></li><li><p>Choose <strong>Submit request</strong>.</p></li></ol><p><img src="'+o+'" alt="The Request waiver form"></p><p>The package stays blocked until a reviewer approves the request.</p><h2 id="track-your-requests" tabindex="-1">Track your requests <a class="header-anchor" href="#track-your-requests" aria-label="Permalink to &quot;Track your requests&quot;">​</a></h2><p>The <strong>Waiver requests</strong> page lists your requests and their status. You only see your own.</p><p><img src="'+i+'" alt="A developer&#39;s waiver requests"></p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Waiting for a security reviewer. You can still edit or withdraw it.</td></tr><tr><td><strong>Approved</strong></td><td>An exception exists. The package installs until the expiry the reviewer set. The request is now locked.</td></tr><tr><td><strong>Rejected</strong></td><td>Not approved. Open it to read the reviewer&#39;s note. Editing a rejected request sends it back for review.</td></tr></tbody></table><p>Choose the eye icon on a request to see its details, including who reviewed it and their note. <strong>Edit</strong> and <strong>Delete</strong> are available there until the request is approved.</p><h2 id="what-happens-on-approval" tabindex="-1">What happens on approval <a class="header-anchor" href="#what-happens-on-approval" aria-label="Permalink to &quot;What happens on approval&quot;">​</a></h2><p>The reviewer sets the expiry date and may narrow or widen the repositories. DepGate then creates an exception with those values. The version installs through DepGate until that date; after it, the version is blocked again.</p><p>The review process for security teams is described in <a href="/depgate/admin/exceptions#review-waiver-requests">Exceptions and waivers</a>.</p>',15)])])}const w=t(n,[["render",d]]);export{g as __pageData,w as default};
